import { log } from '../core/events.js';
import { transferResource } from '../economy/inventories.js';
import { goldPriceToCopper, settleCoinTrade } from '../economy/coin-payments.js';
import { damagedKingdomStructures } from '../settlements/construction.js';

// A royal purchase uses the same marketplace the pawns sell their work into.
// No royal repair materials are generated by a strategic decision.
export const REPAIR_INPUTS = Object.freeze({ wood: 3, stone: 2 });

export function procureKingdomRepairMaterials(world, kingdom) {
  if (!kingdom || !damagedKingdomStructures(world, kingdom.id).length) return [];
  const treasury = kingdom.treasury?.stock;
  const market = kingdom.market?.stock;
  if (!treasury || !market) return [];
  const receipts = [];
  for (const [resource, needed] of Object.entries(REPAIR_INPUTS)) {
    const shortage = Math.max(0, needed - (treasury[resource] || 0));
    if (!(shortage > .001) || (market[resource] || 0) + 1e-8 < shortage) continue;
    const price = kingdom.market.prices?.[resource];
    if (!(price > 0) || !Number.isFinite(price * shortage)) continue;
    const paid = price * shortage;
    const coinMode = treasury.coinMode === true || (treasury.copper || 0) > 0 || (treasury.silver || 0) > 0;
    if (coinMode) {
      const copper = goldPriceToCopper(paid);
      if (!copper || !Number.isSafeInteger(shortage)) continue;
      const result = settleCoinTrade(treasury, market, copper, market, treasury, resource, shortage);
      if (!result) continue;
    } else {
      if (!Number.isFinite(treasury.gold) || treasury.gold + 1e-8 < paid) continue;
      // Both balances and physical stock were preflighted.
      if (transferResource(treasury, market, 'gold', paid) + 1e-8 < paid) continue;
      const moved = transferResource(market, treasury, resource, shortage);
      if (Math.abs(moved - shortage) > 1e-8) throw Error('Royal market procurement not conserved');
    }
    receipts.push({ resource, amount: shortage, priceGold: paid });
  }
  if (receipts.length) {
    kingdom.lastRepairProcurement = { day: world.day, receipts };
    log(world, kingdom.name + ' comprou do mercado '
      + receipts.map(x => x.amount.toFixed(1) + ' ' + x.resource).join(' e ')
      + ' para reparar estruturas danificadas, com recursos já existentes.');
  }
  return receipts;
}
